$e(X_0,F(t_0))=0$. Let $\Gamma:T\to\mathcal{P}(M)\setminus\{\varnothing\}$ be a
set-valued selector of $F$ on $T$ such that $\Gamma(t_0)=X_0$. Since
$\Gamma(1)\subset F(1)=Y$, we find $\alpha_nu_n\in\Gamma(1)$ for some
$n\ge N+1$, and so,
  \begin{align*}
\mbox{\rm V}(\Gamma,[t_0,1])&\ge d_H(\Gamma(t_0),\Gamma(1))\ge e (\Gamma(1),X_0)
  \ge d(\alpha_nu_n,\alpha_1u_1)=|\alpha_n|+|\alpha_1|\\[2pt]
&>|\alpha_1|+\inf_{i\ge N+1}|\alpha_i|={\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)={\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,[t_0,1]).
  \end{align*}

(b) Suppose $t_0=1$ and $X_0:=\{\alpha_1u_1\}$. If
$\Gamma:T\to\mathcal{P}(M)\setminus\{\varnothing\}$ is a set-valued selector of $F$ on $T$,
then $\Gamma(1)\subset F(1)=Y$ implies $\alpha_nu_n\in\Gamma(1)$ for some
$n\ge N+1$, and so,
  \begin{align*}
d_H(X_0,\Gamma(1))&\ge e(\Gamma(1),X_0)\ge d(\alpha_nu_n,\alpha_1u_1)
  =|\alpha_n|+|\alpha_1|\\[2pt]
&>|\alpha_1|+\inf_{i\ge N+1}|\alpha_i|=e(X,Y)\ge e(X_0,Y)=e(X_0,F(t_0)).
  \end{align*}

(c) Clearly, $\mbox{Pr}_XX_0=X_0$. The non-existence of set-valued selectors in (a)
and (b) is again due to the fact that $\mbox{Pr}_YX_0=\varnothing$: in fact, if $y\in Y$,
then $y=\alpha_nu_n$ for some $n\ge N+1$, and so, we have,
for $x\in X_0=\{\alpha_1u_1\}$,
  \begin{equation*}
d(x,y)\!=\!d(\alpha_1u_1,\alpha_nu_n)\!=\!|\alpha_1|+|\alpha_n|
\!>\!\!\inf_{i\ge N+1}(|\alpha_1|+|\alpha_i|)\!=\!\inf_{y\in Y}d(x,y)\!=\!d(x,Y).
  \end{equation*}

(d) We claim that Theorem~\ref{t:BV}(b) holds with $t_0=1$ and $\Gamma(1)=X_0$
(except that $\Gamma(1)\in\mbox{c}(M)$) for every nonempty $X_0\subset Y=F(1)$.

First, observe that $\mbox{Pr}_XY_0=\{\alpha_Nu_N\}$ for every
$\varnothing\ne Y_0\subset Y$ (recall that $X\in\mbox{c}(M)$, and $\mbox{Pr}_XY_0$ is the
set of those $x\in X$, for which $d(y_0,x)=d(y_0,X)$ for some $y_0\in Y_0$).
To see this, we set $n_0:=\min\{n\ge N+1:\alpha_nu_n\in Y_0\}$ for $Y_0\subset Y$.
If $y_0\in Y_0$, we have $y_0=\alpha_nu_n$ for some $n\ge n_0$,
  \begin{equation*}
d(y_0,X)=\inf_{x\in X}d(y_0,x)=\min_{1\le i\le N}(|\alpha_n|+|\alpha_i|)
  =|\alpha_n|+|\alpha_N|,\\[2pt]
  \end{equation*}
and
  \begin{equation*}
\mbox{$d(y_0,x)=|\alpha_n|+|\alpha_i|$ \,if \,$x=\alpha_iu_i\in X$ for some $1\le i\le N$.}
  \end{equation*}
If $n=n_0$ and $i=N$, we find $y_0=\alpha_{n_0}u_{n_0}\in Y_0$,
$x=\alpha_Nu_N\in X$, and
  \begin{equation*}
d(y_0,x)=d(\alpha_{n_0}u_{n_0},\alpha_Nu_N)=|\alpha_{n_0}|+|\alpha_N|=d(y_0,X),
  \end{equation*}
which implies $\alpha_Nu_N\in\mbox{Pr}_XY_0$. Now, if $i<N$, then
$|\alpha_i|>|\alpha_N|$, and so, for every $y_0\in Y_0$, we get
  \begin{equation*}
d(y_0,x)=|\alpha_n|+|\alpha_i|>|\alpha_n|+|\alpha_N|=d(y_0,X).
  \end{equation*}
Thus, $\alpha_iu_i\notin\mbox{Pr}_XY_0$ for all $i=1,\dots,N-1$, and we are through.

Taking the above into account, define a set-valued selector $\Gamma$ of $F$ on $T$
by $\Gamma(t):=\{\alpha_Nu_N\}$ if $0\le t<1$, and $\Gamma(1):=X_0$ with
$X_0=Y_0\subset Y$. It remains to note that $n_0\ge N+1$ implies
  \begin{align*}
{\scriptstyle\overleftarrow{\mbox{\rm V}}}(\Gamma,T)&=e(Y_0,\{\alpha_Nu_N\})=\sup_{y_0\in Y_0}d(y_0,\alpha_Nu_N)
  =|\alpha_{n_0}|+|\alpha_N|\\
&\le|\alpha_{N+1}|+|\alpha_N|={\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T).
  \end{align*}

 \label{ex3}
Making use of an idea from \cite[Example~3.1]{JMAA07}, here we present an example
of a multifunction $F:T\to\mbox{c}(M)$ with $T:=[0,1]$ such that
${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)<+\infty$ and ${\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)=+\infty$ (thus, Theorem~\ref{t:BV}(a) is
applicable to $F$, whereas Theorem~\ref{t:A} is not).

Let $N\in\mathbb{N}$ and $\{\alpha_n\}_{n=1}^\infty\subset(0,+\infty)$ be a
decreasing sequence such that
  \begin{equation} \label{e:Alph}
\lim_{n\to\infty}\alpha_n=0\quad\mbox{and}\quad
\sum_{n=1}^\infty\alpha_{nN}=+\infty
  \end{equation}
(e.g., $\alpha_n=1/n$). Given $n\in\mathbb{N}$, we set
  \begin{equation*}
X_n:=\{0\}\cup\{\alpha_iu_i:1\le i\le nN\},\quad\mbox{and}\quad
X_\infty:=\{0\}\cup\{\alpha_iu_i:i\in\mathbb{N}\}.
  \end{equation*}
Clearly, $X_n\in\mbox{c}(M)$ for all $n\in\mathbb{N}$ and, by the first assumption in \mbox{\rm(\ref{e:Alph})},
the set $X_\infty$ is compact as well. Let $\{\tau_n\}_{n=0}^\infty\subset[0,1)$ be a
strictly increasing sequence such that $\tau_0=0$ and $\lim_{n\to\infty}\tau_n=1$.
Define $F:T\to\mbox{c}(M)$ by the rule:
  \begin{equation*}
\mbox{$F(t):=X_n$ \,if\, $\tau_{n-1}\le t<\tau_n$ for all $n\in\mathbb{N}$, \,and\,
$F(1):=X_\infty$.}
  \end{equation*}
Since $X_n\subset X_{n+1}\subset X_\infty$ for all $n\in\mathbb{N}$, $F$ is nondecreasing
on $T$ (Section~\ref{ss:mon}), and so, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)=0$. In order to see that
${\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)=+\infty$, given $m\in\mathbb{N}$, $m\ge2$, and partition
$\pi_m=\{\tau_n\}_{n=0}^{m-1}\cup\{1\}$ of $T=[0,1]$, we find
  \begin{align}
{\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)&\ge\sum_{n=1}^{m-1}e(F(\tau_n),F(\tau_{n-1}))+e(F(1),F(\tau_{m-1}))
  \nonumber\\
&=\sum_{n=1}^{m-1}e(X_{n+1},X_n)+e(X_\infty,X_m), \label{e:rhs}
  \end{align}
where
  \begin{equation*}
e(X_{n+1},X_n)=\sup_{nN+1\le k\le(n+1)N}\Bigl(|\alpha_k|+
  \inf_{1\le i\le nN}|\alpha_i|\Bigr)=\alpha_{nN+1}+\alpha_{nN}
  \end{equation*}
and
  \begin{equation*}
e(X_\infty,X_m)=\sup_{k\ge mN+1}\Bigl(|\alpha_k|+
  \inf_{1\le i\le mN}|\alpha_i|\Bigr)=\alpha_{mN+1}+\alpha_{mN}.
  \end{equation*}
It follows that the quantity \mbox{\rm(\ref{e:rhs})} is equal to
  \begin{equation*}
\sum_{n=1}^m\alpha_{nN+1}+\sum_{n=1}^m\alpha_{nN}\to+\infty\quad
\mbox{as}\quad m\to\infty.
  \end{equation*}

\begin{align}
\mbox{\rm V}(\Gamma,T)&\ge d_H(\Gamma(t_0),\Gamma(0))=d_H(X_0,\Gamma(0))
  \ge e(\Gamma(0),X_0)\nonumber\\[3pt]
&\ge d(\alpha_iu_i,X_0)\ge d(\alpha_iu_i,X_{n+1}\setminus X_1)\nonumber\\[2pt]
&=\min_{N+1\le k\le (n+1)N}(\alpha_i+\alpha_k)\ge\alpha_{(n+1)N}
  >0={\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T).\label{e:519}
  \end{align}

 \label{t:FuEm}
Suppose a multifunction $F:T\!\times\!\mbox{\rm c}(M)\!\to\!\mbox{\rm c}(M)$
is such that\/{\rm:}
  \begin{itemize}
\item[{\rm(a)}] there is a nondecreasing bounded function $\varphi:T\to\mathbb{R}$ such that
  \begin{equation*}
\mbox{$\!\!\!e(F(s,X),F(t,X))\le\varphi(t)-\varphi(s)$ for all $s,t\in T$, $s\le T$, and
  $X\in\mbox{\rm c}(M);$}
  \end{equation*}
\item[{\rm(b)}] there is a number $0\le\mu<1$ such that
  \begin{equation*}
\mbox{$e(F(t,X),F(t,Y))\le\mu d_H(X,Y)$ for all $t\in T$ and $X,Y\in\mbox{\rm c}(M);$}
  \end{equation*}
\item[{\rm(c)}] there is a multifunction $K:T\to\mbox{\rm c}(M)$ such that
  \begin{equation*}
\mbox{$F(t,X)\subset K(t)$ for all $t\in T$ and $X\in\mbox{\rm c}(M)$.}
  \end{equation*}
  \end{itemize}

If $t_0:=\inf T\in T$ and $X_0\in\mbox{\rm c}(M)$, then there is
$X:T\to\mbox{\rm c}(M)$ such that\\[3pt]
{\rm(i)}~$\mbox{\rm V}(X,T)\le\mbox{\rm V}(\varphi,T)/(1-\mu)<+\infty;$
{\rm(ii)}~$X(t)\subset F(t,X(t))$ for all $t\in T;$\\[3pt]
{\rm(iii)} $d_H(X_0,X(t_0))\le e\bigl(X_0,F(t_0,X(t_0))\bigr)$.
\smallbreak
In addition, if $X_0\subset F(t_0,X_0)$, then {\rm(iii)} can be replaced by $X(t_0)=X_0$.

\begin{equation*}
\mbox{$\!\!\!e(F(s,X),F(t,X))\le\varphi(t)-\varphi(s)$ for all $s,t\in T$, $s\le T$, and
  $X\in\mbox{\rm c}(M);$}
  \end{equation*}

\begin{equation*}
\mbox{$e(F(t,X),F(t,Y))\le\mu d_H(X,Y)$ for all $t\in T$ and $X,Y\in\mbox{\rm c}(M);$}
  \end{equation*}

\begin{equation*}
\mbox{$F(t,X)\subset K(t)$ for all $t\in T$ and $X\in\mbox{\rm c}(M)$.}
  \end{equation*}

If $F_2(t)\!:=\!F(t,X_2(t))$, $t\in T$, then $F_2:T\to\mbox{c}(M)$ and, by \mbox{\rm(\ref{e:XY})},
  \begin{equation*}
e(F_2(s),F_2(t))\le\varphi(t)-\varphi(s)+\mu d_H(X_2(s),X_2(t))\quad
  \forall\,s,t\in T,\,\,s\le t,
  \end{equation*}
and so,
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_2,T)\le\mbox{\rm V}(\varphi,T)+\mu\mbox{\rm V}(X_2,T)\le(1+\mu+\mu^2)\mbox{\rm V}(\varphi,T).

\begin{eqnarray}
&X_n(t)\subset F_{n-1}(t)\!:=\!F(t,X_{n-1}(t))\subset K(t)\quad\mbox{for all $t\in T$,}&
  \label{e:Xnt}\\[3pt]
&d_H(X_0,X_n(t_0))\le e(X_0,F_{n-1}(t_0))\!=\!e\bigl(X_0,F(t_0,X_{n-1}(t_0))\bigr),
